package com.example.quickstart;
import android.app.Activity; import android.content.Intent; import android.os.Bundle; import android.text.InputType; import android.widget.*;

public class RegisterActivity extends Activity {
 @Override protected void onCreate(Bundle b){super.onCreate(b); LinearLayout root=Ui.page(this,"Create account","A few details to get started."); EditText name=Ui.input(this,"Full name",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS); EditText email=Ui.input(this,"Email address",InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS|InputType.TYPE_CLASS_TEXT); EditText pass=Ui.input(this,"Create password (6+ characters)",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD); root.addView(name);root.addView(email);root.addView(pass);root.addView(Ui.button(this,"Create account",()->{String n=Ui.value(name),e=Ui.value(email),p=Ui.value(pass);if(n.isEmpty()||e.isEmpty()||p.length()<6){Ui.toast(this,"Enter all details and a password of at least 6 characters");return;}if(!android.util.Patterns.EMAIL_ADDRESS.matcher(e).matches()){Ui.toast(this,"Enter a valid email address");return;}getSharedPreferences("account",MODE_PRIVATE).edit().putString("name",n).putString("email",e).putString("password",p).apply();Ui.toast(this,"Account created successfully");startActivity(new Intent(this,HomeActivity.class));finish();}));root.addView(Ui.link(this,"Already have an account? Log in",()->finish())); }
}
